SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, s.los, i.status, AVG(p.dod - p.admittime) AS average_days_to_death FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.stay_id = s.stay_id JOIN inputevents i ON i.subject_id = p.subject_id AND i.hadm_id = a.hadm_id AND i.starttime = p.admittime WHERE p.gender = 'M' AND p.anchor_year >= 86 AND p.anchor_year <= 96 AND p.dod IS NOT NULL AND i.itemid = 170275007 AND i.value = 'Sepsis' AND (s.los <= 3/4 OR (s.los > 3/4 AND s.los <= 6/7)) AND (i.endtime - i.starttime) = 1 AND (i.endtime - i.starttime) <= 10 GROUP BY s.los, i.status ORDER BY s.los, i.status NULLS LAST;